class Solution {
    public List<List<Integer>> generate(int numRows) {
        List<List<Integer>> triangle = new ArrayList<>();

        for (int rowIndex = 0; rowIndex < numRows; rowIndex++) {
            List<Integer> row = new ArrayList<>();
            for (int col = 0; col <= rowIndex; col++) {
                if (col == 0 || col == rowIndex) {
                    row.add(1);
                } else {
                    List<Integer> previousRow = triangle.get(rowIndex - 1);
                    row.add(previousRow.get(col - 1) + previousRow.get(col));
                }
            }
            triangle.add(row);
        }

        return triangle;
    }
}

class Solution {
    public List<List<Integer>> generate(int numRows) {
        List<List<Integer>> triangle = new ArrayList<>();

        for (int rowIndex = 0; rowIndex < numRows; rowIndex++) {
            List<Integer> row = new ArrayList<>();
            long value = 1;
            for (int col = 0; col <= rowIndex; col++) {
                row.add((int) value);
                value = value * (rowIndex - col) / (col + 1);
            }
            triangle.add(row);
        }

        return triangle;
    }
}

class Solution {
    public List<List<Integer>> generate(int numRows) {
        List<List<Integer>> triangle = new ArrayList<>();
        List<Integer> row = new ArrayList<>();

        for (int rowIndex = 0; rowIndex < numRows; rowIndex++) {
            row.add(1);
            for (int col = row.size() - 2; col > 0; col--) {
                row.set(col, row.get(col) + row.get(col - 1));
            }
            triangle.add(new ArrayList<>(row));
        }

        return triangle;
    }
}
